package com.hbm.client.generator.industrialmemorial;
import com.hbm.machine.generator.industrialmemorial.IndustrialMemorialContent;import mezz.jei.api.*;import mezz.jei.api.constants.VanillaTypes;import mezz.jei.api.registration.*;import net.minecraft.network.chat.Component;import net.minecraft.resources.ResourceLocation;
@JeiPlugin public final class IndustrialMemorialJeiPlugin implements IModPlugin {@Override public ResourceLocation getPluginUid(){return ResourceLocation.parse("hbm:industrial_memorial");}@Override public void registerExtraIngredients(IExtraIngredientRegistration event){event.addExtraIngredients(VanillaTypes.ITEM_STACK,IndustrialMemorialContent.allStacks());}@Override public void registerRecipes(IRecipeRegistration event){event.addIngredientInfo(IndustrialMemorialContent.allStacks(),VanillaTypes.ITEM_STACK,Component.translatable("gui.hbm.industrial_memorial.text"));}}
